package com.leetcode.backend.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class AssessmentMaintenanceScheduler {private final AssessmentService service;private final AssessmentCreatorService creators;private final int timeout;private final int retentionDays;AssessmentMaintenanceScheduler(AssessmentService s,AssessmentCreatorService c,@Value("${verdixa.assessment.heartbeat-timeout-seconds:40}") int t,@Value("${verdixa.verification.retention-days:30}") int retention){service=s;creators=c;timeout=t;retentionDays=retention;}@Scheduled(fixedDelayString="${verdixa.assessment.maintenance-ms:30000}") public void expire(){service.expireHeartbeats(timeout);}@Scheduled(cron="0 17 3 * * *") public void purgeDocuments(){creators.purgeExpiredDocuments(retentionDays);}}
